/* ==================== DESKTOP CSC PREMIUM (≥ 1280px) ==================== */
@media (min-width: 1280px) {

  body {
    background:
      radial-gradient(circle at top left, rgba(59,130,246,0.10), transparent 28%),
      radial-gradient(circle at bottom right, rgba(16,185,129,0.08), transparent 30%),
      linear-gradient(180deg, #061018 0%, #0a1622 45%, #08121b 100%);
  }

  .container {
    padding: 30px;
    gap: 22px;
  }

  /* ================= HEADER ================= */

  .header-row {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-between;

    width: 100%;
    min-height: 108px;

    padding: 24px 32px;

    border-radius: 26px;

    background:
      linear-gradient(180deg,
        rgba(10,18,28,0.96),
        rgba(7,14,22,0.94));

    border: 1px solid rgba(59,130,246,0.10);

    box-shadow:
      0 12px 40px rgba(0,0,0,0.46),
      inset 0 1px 0 rgba(255,255,255,0.025);

    overflow: hidden;

    pointer-events: none;
  }

  .title-group,
  .title-group *,
  .actions,
  .actions * {
    pointer-events: auto;
  }

  .header-row::before {
    content: '';
    position: absolute;
    inset: 0;

    background:
      linear-gradient(90deg,
        rgba(59,130,246,0.06),
        transparent 35%,
        transparent 65%,
        rgba(16,185,129,0.04));

    pointer-events: none;
  }

  /* ================= TITLE ================= */

  .title-group {
    position: relative;
    z-index: 2;

    flex: 1;
    max-width: 72%;

    padding: 0;
    background: transparent;
    border: none;
    box-shadow: none;
  }

  .title {
    font-size: 42px;
    line-height: 1.06;

    font-weight: 800;
    letter-spacing: -0.035em;

    color: #f8fbff;

    margin: 0 0 14px 0;

    white-space: normal;
    overflow: visible;
    text-overflow: unset;

    text-shadow: 0 2px 18px rgba(0,0,0,0.42);
  }

  .subtitle {
    display: inline-flex;
    align-items: center;
    gap: 8px;

    font-size: 13px;
    font-weight: 800;
    letter-spacing: 0.12em;
    text-transform: uppercase;

    color: #3b82f6;

    margin-bottom: 10px;

    transition: opacity 0.2s ease;
  }

  .subtitle:hover {
    opacity: 0.88;
  }

  .subtitle::before {
    content: '';

    width: 7px;
    height: 7px;

    border-radius: 999px;

    background: #10b981;

    box-shadow: 0 0 12px rgba(16,185,129,0.75);
  }

  .sources {
    display: block;

    font-size: 13px;
    line-height: 1.7;

    color: #8ea1b5;

    max-width: 1000px;
  }

  .sources a {
    color: #d7e3f0;
    text-decoration: none;

    transition:
      color 0.2s ease,
      opacity 0.2s ease;
  }

  .sources a:hover {
    color: #60a5fa;
  }

  /* ================= ACTIONS ================= */

  .actions {
    position: relative;
    z-index: 2;

    display: flex;
    align-items: center;
    gap: 10px;

    padding: 10px;

    border-radius: 20px;

    background: rgba(255,255,255,0.022);

    border: 1px solid rgba(59,130,246,0.08);
  }

  .btn {
    position: relative;

    width: 50px;
    height: 50px;

    border-radius: 15px;

    border: 1px solid rgba(255,255,255,0.05);

    background:
      linear-gradient(180deg,
        rgba(255,255,255,0.04),
        rgba(255,255,255,0.018));

    color: #f8fbff;

    display: flex;
    align-items: center;
    justify-content: center;

    cursor: pointer;

    transition:
      transform 0.18s ease,
      background 0.18s ease,
      border-color 0.18s ease,
      box-shadow 0.18s ease;
  }

  .btn:hover {
    transform: translateY(-2px);

    border-color: rgba(59,130,246,0.24);

    background:
      linear-gradient(180deg,
        rgba(59,130,246,0.16),
        rgba(16,185,129,0.05));

    box-shadow:
      0 10px 26px rgba(0,0,0,0.34),
      0 0 20px rgba(59,130,246,0.14);
  }

  .btn:active {
    transform: scale(0.96);
  }

  .btn svg {
    width: 22px;
    height: 22px;
    fill: currentColor;
  }

  .btn.nav-btn {
    color: #60a5fa;
  }

  .btn.nav-btn svg {
    width: 26px;
    height: 26px;
    stroke: currentColor;
    stroke-width: 2.4;
    fill: none;
  }

  .actions div[style*='width:1px'] {
    width: 1px !important;
    height: 30px !important;
    background: rgba(255,255,255,0.07) !important;
    margin: 0 2px !important;
  }

  /* ================= CHART CONTAINER ================= */

  #full-capture-area {
    position: relative;

    overflow: hidden;

    border-radius: 28px;

    background:
      linear-gradient(180deg,
        rgba(9,17,27,0.98),
        rgba(6,13,21,0.98));

    border: 1px solid rgba(59,130,246,0.08);

    box-shadow:
      0 25px 60px rgba(0,0,0,0.50),
      inset 0 1px 0 rgba(255,255,255,0.02);
  }

  #full-capture-area::before {
    content: '';

    position: absolute;
    inset: 0;

    background:
      linear-gradient(180deg,
        rgba(255,255,255,0.022),
        transparent 18%);

    pointer-events: none;
  }

  .chart-container {
    position: relative;

    display: flex;
    justify-content: center;
    align-items: center;

    width: 100%;
    height: 100%;

    padding: 42px;
  }

  .chart-container img {
    width: auto;
    height: auto;

    max-width: 100%;
    max-height: calc(100vh - 255px);

    object-fit: contain;

    border-radius: 16px;

    box-shadow:
      0 24px 70px rgba(0,0,0,0.58),
      0 0 0 1px rgba(255,255,255,0.025);

    transition:
      transform 0.3s ease,
      box-shadow 0.3s ease;
  }

  .chart-container img:hover {
    transform: scale(1.006);

    box-shadow:
      0 34px 90px rgba(0,0,0,0.68),
      0 0 0 1px rgba(59,130,246,0.10);
  }

  /* ================= SCROLLBAR ================= */

  ::-webkit-scrollbar {
    width: 10px;
    height: 10px;
  }

  ::-webkit-scrollbar-thumb {
    background: rgba(255,255,255,0.10);
    border-radius: 999px;
  }

  ::-webkit-scrollbar-thumb:hover {
    background: rgba(59,130,246,0.24);
  }
}
